{
  "name": "Podea - Intelligent Studio Check-in",
  "description": "A high-fidelity PWA prototype for Podea, a SaaS product providing an intelligent check-in and compliance layer for medical foot care, wellness, and beauty studios. This prototype showcases the marketing landing page and a role-based interactive demo."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
    throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
    <React.StrictMode>
        <App />
    </React.StrictMode>
);

import React, { useState } from 'react';
import { LanguageProvider } from './context/LanguageContext';
import LandingPage from './pages/LandingPage';
import DemoApp from './pages/DemoApp';
import { View } from './types';

export default function App() {
    const [view, setView] = useState<View>('landing');

    const renderView = () => {
        switch (view) {
            case 'landing':
                return <LandingPage onStartDemo={() => setView('roleSelector')} />;
            case 'roleSelector':
            case 'adminDashboard':
            case 'adminSettings':
            case 'practitionerArrivals':
            case 'practitionerClient':
            case 'tabletCheckin':
                return <DemoApp initialView={view} setView={setView} />;
            default:
                return <LandingPage onStartDemo={() => setView('roleSelector')} />;
        }
    };

    return (
        <LanguageProvider>
            <div className="min-h-screen bg-p-background">
                {renderView()}
            </div>
        </LanguageProvider>
    );
}

export type Language = 'de' | 'en';

export interface Translations {
  de: string;
  en: string;
}

export type Role = 'admin' | 'practitioner' | 'tablet';

export type View = 
  | 'landing'
  | 'roleSelector'
  | 'adminDashboard'
  | 'adminSettings'
  | 'practitionerArrivals'
  | 'practitionerClient'
  | 'tabletCheckin';

export interface Client {
  id: number;
  name: string;
  phone: string;
  appointmentTime: string;
  practitioner: string;
  status: 'waiting' | 'in-progress' | 'done' | 'late';
  medicalFlags: string[];
  lastTreatment: string;
  notes: string[];
  suggestedUpsells: { name: string; price: number }[];
}

export interface Service {
    name: string;
    price: number;
    vat: number;
    duration: number;
}

export interface Addon {
    name: string;
    price: number;
}

export interface Product {
    name: string;
    type: 'retail' | 'consumable';
    stock: number;
    lowStockThreshold: number;
}

import React, { createContext, useState, useContext, ReactNode } from 'react';
import { Language, Translations } from '../types';

interface LanguageContextType {
    language: Language;
    setLanguage: (lang: Language) => void;
    t: (translations: Translations) => string;
}

const LanguageContext = createContext<LanguageContextType | undefined>(undefined);

export const LanguageProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [language, setLanguage] = useState<Language>('de');

    const t = (translations: Translations) => {
        return translations[language];
    };

    return (
        <LanguageContext.Provider value={{ language, setLanguage, t }}>
            {children}
        </LanguageContext.Provider>
    );
};

export const useLanguage = () => {
    const context = useContext(LanguageContext);
    if (context === undefined) {
        throw new Error('useLanguage must be used within a LanguageProvider');
    }
    return context;
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: 'primary' | 'secondary' | 'accent';
    children: React.ReactNode;
}

const Button: React.FC<ButtonProps> = ({ variant = 'primary', children, className, ...props }) => {
    const baseStyles = 'px-6 py-3 font-medium rounded-lg shadow-sm transition-all duration-300 focus:outline-none focus:ring-2 focus:ring-offset-2';

    const variantStyles = {
        primary: 'bg-p-primary text-white hover:bg-opacity-90 focus:ring-p-primary',
        secondary: 'bg-white text-p-primary border border-gray-300 hover:bg-gray-50 focus:ring-p-primary',
        accent: 'bg-p-accent text-p-primary hover:bg-opacity-90 focus:ring-p-accent',
    };

    return (
        <button className={`${baseStyles} ${variantStyles[variant]} ${className}`} {...props}>
            {children}
        </button>
    );
};

export default Button;

import React from 'react';

interface CardProps {
    children: React.ReactNode;
    className?: string;
    onClick?: () => void;
}

const Card: React.FC<CardProps> = ({ children, className, onClick }) => {
    const clickableStyles = onClick ? 'cursor-pointer hover:shadow-lg transition-shadow duration-300' : '';
    return (
        <div 
            className={`bg-white rounded-xl shadow-md overflow-hidden p-6 md:p-8 ${clickableStyles} ${className}`}
            onClick={onClick}
        >
            {children}
        </div>
    );
};

export default Card;

import React from 'react';
import { useLanguage } from '../../context/LanguageContext';

const LanguageToggle: React.FC = () => {
    const { language, setLanguage } = useLanguage();

    const toggleLanguage = () => {
        setLanguage(language === 'de' ? 'en' : 'de');
    };

    return (
        <div className="flex items-center space-x-2 text-sm font-medium text-p-primary">
            <span className={`${language === 'de' ? 'font-bold' : 'opacity-70'}`}>DE</span>
            <button
                onClick={toggleLanguage}
                className="relative inline-flex h-6 w-11 flex-shrink-0 cursor-pointer rounded-full border-2 border-transparent bg-gray-300 transition-colors duration-200 ease-in-out focus:outline-none focus:ring-2 focus:ring-p-accent focus:ring-offset-2"
            >
                <span
                    className={`${
                        language === 'en' ? 'translate-x-5' : 'translate-x-0'
                    } inline-block h-5 w-5 transform rounded-full bg-white shadow ring-0 transition duration-200 ease-in-out`}
                />
            </button>
            <span className={`${language === 'en' ? 'font-bold' : 'opacity-70'}`}>EN</span>
        </div>
    );
};

export default LanguageToggle;

import React from 'react';

const CheckCircleIcon: React.FC<{ className?: string }> = ({ className }) => (
    <svg xmlns="http://www.w3.org/2000/svg" className={className} fill="none" viewBox="0 0 24 24" stroke="currentColor">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
    </svg>
);

export default CheckCircleIcon;

import React, { useState } from 'react';
import { View } from '../types';
import RoleSelector from '../components/app/RoleSelector';
import AdminDashboard from '../components/app/admin/AdminDashboard';
import AdminSettings from '../components/app/admin/AdminSettings';
import PractitionerArrivals from '../components/app/practitioner/PractitionerArrivals';
import ClientDetailView from '../components/app/practitioner/ClientDetailView';
import TabletCheckinFlow from '../components/app/tablet/TabletCheckinFlow';
import { Client } from '../types';
import { clients } from '../data/mockData';

interface DemoAppProps {
    initialView: View;
    setView: (view: View) => void;
}

const DemoApp: React.FC<DemoAppProps> = ({ initialView, setView }) => {
    const [currentView, setCurrentView] = useState<View>(initialView);
    const [selectedClient, setSelectedClient] = useState<Client | null>(clients[0]);

    const handleSelectClient = (client: Client) => {
        setSelectedClient(client);
        setCurrentView('practitionerClient');
    };

    const renderContent = () => {
        switch (currentView) {
            case 'roleSelector':
                return <RoleSelector setView={setCurrentView} />;
            case 'adminDashboard':
                return <AdminDashboard setView={setCurrentView} />;
            case 'adminSettings':
                return <AdminSettings setView={setCurrentView} />;
            case 'practitionerArrivals':
                return <PractitionerArrivals setView={setCurrentView} onSelectClient={handleSelectClient} />;
            case 'practitionerClient':
                return <ClientDetailView setView={setCurrentView} client={selectedClient} />;
            case 'tabletCheckin':
                return <TabletCheckinFlow setView={setCurrentView} />;
            default:
                return <RoleSelector setView={setCurrentView} />;
        }
    };

    return (
        <div className="min-h-screen bg-gray-100">
           {renderContent()}
        </div>
    );
};

export default DemoApp;

import React from 'react';
