import React, { useState } from 'react';
import AppHeader from '../AppHeader';
import Card from '../../ui/Card';
import { View } from '../../../types';
import { services, addons, products } from '../../../data/mockData';

type Tab = 'services' | 'addons' | 'products';

const AdminSettings: React.FC<{ setView: (view: View) => void }> = ({ setView }) => {
    const [activeTab, setActiveTab] = useState<Tab>('services');

    const renderContent = () => {
        switch (activeTab) {
            case 'services':
                return (
                    <table className="w-full text-left">
                        <thead><tr className="border-b"><th className="p-3">Leistung</th><th className="p-3">Preis</th><th className="p-3">Dauer</th></tr></thead>
                        <tbody>{services.map(s => <tr key={s.name} className="border-b"><td className="p-3">{s.name}</td><td className="p-3">€{s.price.toFixed(2)}</td><td className="p-3">{s.duration} Min</td></tr>)}</tbody>
                    </table>
                );
            case 'addons':
                return (
                    <table className="w-full text-left">
                        <thead><tr className="border-b"><th className="p-3">Add-on</th><th className="p-3">Preis</th></tr></thead>
                        <tbody>{addons.map(a => <tr key={a.name} className="border-b"><td className="p-3">{a.name}</td><td className="p-3">€{a.price.toFixed(2)}</td></tr>)}</tbody>
                    </table>
                );
            case 'products':
                return (
                    <table className="w-full text-left">
                        <thead><tr className="border-b"><th className="p-3">Produkt</th><th className="p-3">Typ</th><th className="p-3">Lagerbestand</th></tr></thead>
                        <tbody>{products.map(p => <tr key={p.name} className={`border-b ${p.stock < p.lowStockThreshold ? 'bg-red-50' : ''}`}><td className="p-3">{p.name}</td><td className="p-3">{p.type}</td><td className="p-3">{p.stock} {p.stock < p.lowStockThreshold && <span className="text-p-warning text-xs ml-2">(Niedrig)</span>}</td></tr>)}</tbody>
                    </table>
                );
        }
    };

    const TabButton: React.FC<{tabId: Tab, children: React.ReactNode}> = ({tabId, children}) => (
        <button 
            onClick={() => setActiveTab(tabId)}
            className={`px-4 py-2 font-medium text-sm rounded-md ${activeTab === tabId ? 'bg-p-primary text-white' : 'text-gray-600 hover:bg-gray-200'}`}
        >{children}</button>
    );

    return (
        <div className="min-h-screen bg-gray-50">
            <AppHeader title="Einstellungen" role="Studio Admin" setView={setView} />
            <main className="max-w-7xl mx-auto p-4 sm:p-6 lg:p-8">
                <button onClick={() => setView('adminDashboard')} className="mb-6 text-sm text-gray-600 hover:text-p-primary">&larr; Zurück zum Dashboard</button>
                <Card>
                    <div className="border-b mb-6 pb-4">
                        <div className="flex items-center gap-2">
                           <TabButton tabId="services">Leistungen</TabButton>
                           <TabButton tabId="addons">Add-ons</TabButton>
                           <TabButton tabId="products">Produkte</TabButton>
                        </div>
                    </div>
                    <div className="overflow-x-auto">
                        {renderContent()}
                    </div>
                </Card>
            </main>
        </div>
    );
};

export default AdminSettings;

import React from 'react';
import AppHeader from '../AppHeader';
import Card from '../../ui/Card';
import { View, Client } from '../../../types';
import { clients } from '../../../data/mockData';
import { BellIcon } from '@heroicons/react/solid';

const PractitionerArrivals: React.FC<{ setView: (view: View) => void; onSelectClient: (client: Client) => void; }> = ({ setView, onSelectClient }) => {
    const practitionerClients = clients.filter(c => c.practitioner === 'Sabine Weber');

    const getStatusColor = (status: Client['status']) => {
        switch (status) {
            case 'waiting': return 'border-blue-500';
            case 'in-progress': return 'border-p-accent';
            case 'done': return 'border-p-success';
            default: return 'border-gray-300';
        }
    };

    return (
        <div className="min-h-screen bg-gray-50">
            <AppHeader title="Meine Ankünfte" role="Behandler/in: Sabine Weber" setView={setView} />
            <main className="max-w-7xl mx-auto p-4 sm:p-6 lg:p-8">
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {practitionerClients.map(client => (
                        <Card key={client.id} onClick={() => onSelectClient(client)} className={`border-l-4 ${getStatusColor(client.status)}`}>
                            <div className="flex justify-between items-start">
                                <div>
                                    <p className="text-lg font-semibold text-p-primary">{client.name}</p>
                                    <p className="text-gray-600">{client.appointmentTime} Uhr</p>
                                </div>
                                {client.medicalFlags.length > 0 && (
                                    <div className="flex-shrink-0 text-p-warning" title={client.medicalFlags.join(', ')}>
                                        <BellIcon className="w-6 h-6"/>
                                    </div>
                                )}
                            </div>
                            <div className="mt-4 pt-4 border-t">
                                <p className="text-sm text-gray-500">{client.lastTreatment}</p>
                            </div>
                        </Card>
                    ))}
                </div>
            </main>
        </div>
    );
};

export default PractitionerArrivals;

import React, { useState, useEffect } from 'react';
import { View } from '../../../types';
import Button from '../../ui/Button';
import { CheckCircleIcon } from '@heroicons/react/solid';

const WelcomeScreen: React.FC<{ onNext: () => void }> = ({ onNext }) => (
    <div className="text-center">
        <h1 className="text-5xl font-medium mb-4">Willkommen bei</h1>
        <h2 className="text-3xl font-semibold text-p-accent mb-12">Studio Eleganz</h2>
        <Button onClick={onNext} variant="accent" className="text-xl py-4 px-12">Check-in starten</Button>
    </div>
);

const PhoneInputScreen: React.FC<{ onNext: (phone: string) => void }> = ({ onNext }) => {
    const [phone, setPhone] = useState('');

    const handleKeyClick = (key: string) => {
        if (key === 'del') {
            setPhone(p => p.slice(0, -1));
        } else if (phone.length < 10) {
            setPhone(p => p + key);
        }
    };

    return (
        <div className="text-center w-full max-w-sm">
            <h2 className="text-3xl font-medium mb-2">Ihre Mobilfunknummer</h2>
            <p className="text-gray-300 mb-8">Zur Identifizierung Ihres Termins.</p>
            <div className="h-16 w-full bg-white/10 rounded-lg flex items-center justify-center text-4xl tracking-widest font-mono mb-8">
                {phone}
            </div>
            <div className="grid grid-cols-3 gap-4">
                {'123456789'.split('').map(k => <button key={k} onClick={() => handleKeyClick(k)} className="h-16 text-3xl bg-white/10 rounded-lg hover:bg-white/20 transition">{k}</button>)}
                <div/>
                <button onClick={() => handleKeyClick('0')} className="h-16 text-3xl bg-white/10 rounded-lg hover:bg-white/20 transition">0</button>
                <button onClick={() => handleKeyClick('del')} className="h-16 text-2xl bg-white/10 rounded-lg hover:bg-white/20 transition">&larr;</button>
            </div>
            <Button disabled={phone.length < 4} onClick={() => onNext(phone)} variant="accent" className="w-full mt-8 text-xl py-4">Weiter</Button>
        </div>
    );
};

const ConfirmationScreen: React.FC<{ title: string; subtitle: string; onNext: () => void; buttonText: string }> = ({ title, subtitle, onNext, buttonText }) => (
    <div className="text-center max-w-lg">
        <h2 className="text-4xl font-medium mb-4">{title}</h2>
        <p className="text-gray-300 mb-12 text-lg">{subtitle}</p>
        <Button onClick={onNext} variant="accent" className="text-xl py-4 px-12">{buttonText}</Button>
    </div>
);

const HealthQuestionScreen: React.FC<{ onNext: () => void }> = ({ onNext }) => (
    <div className="text-center max-w-lg">
        <h2 className="text-4xl font-medium mb-4">Eine letzte Frage...</h2>
        <p className="text-gray-300 mb-12 text-lg">Haben sich seit Ihrem letzten Besuch relevante gesundheitliche Änderungen ergeben (z.B. neue Medikamente, Allergien)?</p>
        <div className="flex gap-6 justify-center">
            <Button onClick={onNext} variant="secondary" className="text-xl py-4 px-12 bg-white/80">Nein, keine Änderungen</Button>
            <Button onClick={onNext} variant="accent" className="text-xl py-4 px-12">Ja, es gibt Änderungen</Button>
        </div>
    </div>
);

const ArrivalScreen: React.FC = () => (
    <div className="text-center max-w-lg">
        <CheckCircleIcon className="w-24 h-24 text-p-accent mx-auto mb-8"/>
        <h2 className="text-4xl font-medium mb-4">Vielen Dank!</h2>
        <p className="text-gray-300 text-lg">Sie sind erfolgreich angemeldet. Bitte nehmen Sie im Wartebereich Platz. Ihr/e Behandler/in wird Sie in Kürze aufrufen.</p>
    </div>
);


type Step = 'welcome' | 'phone' | 'recognition' | 'consent' | 'health' | 'arrival';

const TabletCheckinFlow: React.FC<{ setView: (view: View) => void }> = ({ setView }) => {
    const [step, setStep] = useState<Step>('welcome');

    useEffect(() => {
        if (step === 'arrival') {
            const timer = setTimeout(() => {
                setStep('welcome');
            }, 5000);
            return () => clearTimeout(timer);
        }
    }, [step]);

    const renderStep = () => {
        switch (step) {
            case 'welcome':
                return <WelcomeScreen onNext={() => setStep('phone')} />;
            case 'phone':
                return <PhoneInputScreen onNext={() => setStep('recognition')} />;
            case 'recognition':
                return <ConfirmationScreen title="Willkommen zurück, Anna Schmidt!" subtitle="" onNext={() => setStep('consent')} buttonText="Bestätigen & weiter" />;
            case 'consent':
                return <ConfirmationScreen title="Einverständnis" subtitle="Ich bestätige die AGB und die Datenschutzerklärung gelesen und verstanden zu haben." onNext={() => setStep('health')} buttonText="Zustimmen" />;
            case 'health':
                return <HealthQuestionScreen onNext={() => setStep('arrival')} />;
            case 'arrival':
                return <ArrivalScreen />;
            default:
                return null;
        }
    };

    return (
        <div className="fixed inset-0 bg-p-primary text-white flex flex-col items-center justify-center p-8">
            <button onClick={() => setView('roleSelector')} className="absolute top-4 left-4 text-white/50 hover:text-white transition">&larr; Demo verlassen</button>
            {renderStep()}
        </div>
    );
};

export default TabletCheckinFlow;

