import React, { useState } from 'react';
import AppHeader from '../AppHeader';
import Card from '../../ui/Card';
import Button from '../../ui/Button';
import { View } from '../../../types';
import { services as initialServices, addons as initialAddons, products as initialProducts } from '../../../data/mockData';
import { PencilSquareIcon, CheckIcon } from '@heroicons/react/24/outline';

type Tab = 'services' | 'addons' | 'products';

const AdminSettings: React.FC<{ setView: (view: View) => void }> = ({ setView }) => {
    const [activeTab, setActiveTab] = useState<Tab>('services');
    const [isEditing, setIsEditing] = useState(false);

    // Local state for edits
    const [services, setServices] = useState(initialServices);
    const [products, setProducts] = useState(initialProducts);

    const handleServiceChange = (index: number, field: string, value: string) => {
        const newServices = [...services];
        (newServices[index] as any)[field] = field === 'name' ? value : Number(value);
        setServices(newServices);
    };

    const handleProductChange = (index: number, field: string, value: string) => {
        const newProducts = [...products];
        (newProducts[index] as any)[field] = field === 'name' ? value : Number(value);
        setProducts(newProducts);
    };

    const renderContent = () => {
        switch (activeTab) {
            case 'services':
                return (
                    <table className="w-full text-left">
                        <thead><tr className="border-b border-p-stone"><th className="p-4 text-xs font-bold uppercase tracking-widest text-p-text/50">Leistung</th><th className="p-4 text-xs font-bold uppercase tracking-widest text-p-text/50">Preis (€)</th><th className="p-4 text-xs font-bold uppercase tracking-widest text-p-text/50">Dauer (Min)</th></tr></thead>
                        <tbody>{services.map((s, i) => (
                            <tr key={i} className="border-b border-p-stone/40 hover:bg-p-surface transition-colors">
                                <td className="p-4 font-medium text-p-primary">
                                    {isEditing ? <input className="w-full bg-white border border-p-stone rounded px-2 py-1" value={s.name} onChange={(e) => handleServiceChange(i, 'name', e.target.value)} /> : s.name}
                                </td>
                                <td className="p-4 text-p-text">
                                     {isEditing ? <input type="number" className="w-20 bg-white border border-p-stone rounded px-2 py-1" value={s.price} onChange={(e) => handleServiceChange(i, 'price', e.target.value)} /> : `€${s.price.toFixed(2)}`}
                                </td>
                                <td className="p-4 text-p-text">
                                     {isEditing ? <input type="number" className="w-20 bg-white border border-p-stone rounded px-2 py-1" value={s.duration} onChange={(e) => handleServiceChange(i, 'duration', e.target.value)} /> : `${s.duration} Min`}
                                </td>
                            </tr>
                        ))}</tbody>
                    </table>
                );
            case 'addons':
                return (
                    <div className="p-8 text-center text-p-text/50 italic">Add-ons Bearbeitung in dieser Demo deaktiviert.</div>
                );
            case 'products':
                return (
                    <table className="w-full text-left">
                        <thead><tr className="border-b border-p-stone"><th className="p-4 text-xs font-bold uppercase tracking-widest text-p-text/50">Produkt</th><th className="p-4 text-xs font-bold uppercase tracking-widest text-p-text/50">Typ</th><th className="p-4 text-xs font-bold uppercase tracking-widest text-p-text/50">Lagerbestand</th></tr></thead>
                        <tbody>{products.map((p, i) => (
                            <tr key={i} className={`border-b border-p-stone/40 hover:bg-p-surface transition-colors ${p.stock < p.lowStockThreshold ? 'bg-p-warning/5' : ''}`}>
                                <td className="p-4 font-medium text-p-primary">{p.name}</td>
                                <td className="p-4 text-p-text capitalize">{p.type}</td>
                                <td className="p-4 text-p-text">
                                    {isEditing ? (
                                        <input type="number" className="w-20 bg-white border border-p-stone rounded px-2 py-1" value={p.stock} onChange={(e) => handleProductChange(i, 'stock', e.target.value)} />
                                    ) : (
                                        <>
                                            {p.stock} 
                                            {p.stock < p.lowStockThreshold && <span className="text-p-warning text-[10px] uppercase font-bold tracking-wider ml-2">Niedrig</span>}
                                        </>
                                    )}
                                </td>
                            </tr>
                        ))}</tbody>
                    </table>
                );
        }
    };

    const TabButton: React.FC<{tabId: Tab, children: React.ReactNode}> = ({tabId, children}) => (
        <button 
            onClick={() => setActiveTab(tabId)}
            className={`px-6 py-2.5 font-medium text-sm rounded-full transition-all duration-300 ${activeTab === tabId ? 'bg-p-primary text-white shadow-soft' : 'text-p-text/60 hover:text-p-primary hover:bg-p-surface'}`}
        >{children}</button>
    );

    return (
        <div className="min-h-screen bg-p-background">
            <AppHeader title="Einstellungen" role="Studio Admin" setView={setView} />
            <main className="max-w-7xl mx-auto p-6 md:p-10">
                <div className="flex justify-between items-center mb-8">
                    <button onClick={() => setView('adminDashboard')} className="text-xs font-bold uppercase tracking-widest text-p-text/50 hover:text-p-primary transition-colors">&larr; Zurück zum Dashboard</button>
                    <Button variant={isEditing ? 'success' : 'secondary'} onClick={() => setIsEditing(!isEditing)} className="flex items-center gap-2 px-6 py-2">
                         {isEditing ? <><CheckIcon className="w-4 h-4"/> Speichern</> : <><PencilSquareIcon className="w-4 h-4"/> Bearbeiten</>}
                    </Button>
                </div>

                <Card>
                    <div className="border-b border-p-stone mb-8 pb-6">
                        <div className="flex items-center gap-2">
                           <TabButton tabId="services">Leistungen</TabButton>
                           <TabButton tabId="addons">Add-ons</TabButton>
                           <TabButton tabId="products">Produkte</TabButton>
                        </div>
                    </div>
                    <div className="overflow-x-auto">
                        {renderContent()}
                    </div>
                </Card>
            </main>
        </div>
    );
};

export default AdminSettings;

