    const [services, setServices] = useState(initialServices);
    const [products, setProducts] = useState(initialProducts);
    const [rules, setRules] = useState(initialRules);

    const handleServiceChange = (index: number, field: string, value: string) => {
        const newServices = [...services];
        (newServices[index] as any)[field] = field === 'name' ? value : Number(value);
        setServices(newServices);
    };

    const handleProductChange = (index: number, field: string, value: string) => {
        const newProducts = [...products];
        (newProducts[index] as any)[field] = field === 'name' ? value : Number(value);
        setProducts(newProducts);
    };

    const toggleRule = (id: number) => {
        setRules(rules.map(r => r.id === id ? { ...r, active: !r.active } : r));
    };

    const renderContent = () => {
        switch (activeTab) {
            case 'services':
                return (
                    <table className="w-full text-left">
                        <thead><tr className="border-b border-p-stone"><th className="p-4 text-xs font-bold uppercase tracking-widest text-p-text/50">Leistung</th><th className="p-4 text-xs font-bold uppercase tracking-widest text-p-text/50">Preis (€)</th><th className="p-4 text-xs font-bold uppercase tracking-widest text-p-text/50">Dauer (Min)</th></tr></thead>
