                return (
                    <table className="w-full text-left">
                        <thead><tr className="border-b border-p-stone"><th className="p-4 text-xs font-bold uppercase tracking-widest text-p-text/50">Produkt</th><th className="p-4 text-xs font-bold uppercase tracking-widest text-p-text/50">Typ</th><th className="p-4 text-xs font-bold uppercase tracking-widest text-p-text/50">Lagerbestand</th></tr></thead>
                        <tbody>{products.map((p, i) => (
                            <tr key={i} className={`border-b border-p-stone/40 hover:bg-p-surface transition-colors ${p.stock < p.lowStockThreshold ? 'bg-p-warning/5' : ''}`}>
