                        <div className="flex flex-col items-end gap-2">
                             <Button 
                                variant="primary" 
                                onClick={handleStartTreatment} 
                                disabled={!isSafetyCheckComplete}
                                className={`flex items-center gap-2 pl-6 pr-8 ${!isSafetyCheckComplete ? 'opacity-50 cursor-not-allowed bg-gray-400' : ''}`}
                            >
                                {isSafetyCheckComplete ? <PlayIcon className="w-4 h-4" /> : <LockClosedIcon className="w-4 h-4" />} 
                                Behandlung starten
                            </Button>
                            {!isSafetyCheckComplete && (
                                <span className="text-[10px] uppercase tracking-widest text-p-warning font-bold animate-pulse">
                                    Sicherheits-Check erforderlich
                                </span>
                            )}
                        </div>
                    )}
                    {status === 'in-progress' && (
                        <Button variant="accent" onClick={handleFinishTreatment} className="flex items-center gap-2 pl-6 pr-8">
                            <CheckIcon className="w-4 h-4" /> Behandlung abschließen
