const ClientDetailView: React.FC<{ setView: (view: View) => void; client: Client | null }> = ({ setView, client }) => {
    const [status, setStatus] = useState<Client['status']>(client?.status || 'waiting');

    // Safety check state with timestamps
    const [checklist, setChecklist] = useState<{
        risk: boolean;
        riskTime: string | null;
        kit: boolean;
        kitTime: string | null;
    }>({ 
        risk: false, 
        riskTime: null,
        kit: false, 
        kitTime: null 
    });

    const [upsellSold, setUpsellSold] = useState(false);

    if (!client) {
        return (
            <div className="flex items-center justify-center h-screen bg-p-background">
                <p>Client not found.</p>
                <button onClick={() => setView('practitionerArrivals')}>Go back</button>
            </div>
        );
    }

    const getCurrentTime = () => new Date().toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' });

    const toggleRisk = () => {
        setChecklist(prev => ({
            ...prev,
            risk: !prev.risk,
            riskTime: !prev.risk ? getCurrentTime() : null
        }));
    };

    const toggleKit = () => {
        setChecklist(prev => ({
            ...prev,
            kit: !prev.kit,
            kitTime: !prev.kit ? getCurrentTime() : null
        }));
    };

    const handleStartTreatment = () => {
        setStatus('in-progress');
    };

    const handleFinishTreatment = () => {
        setStatus('done');
    };

    const isSafetyCheckComplete = checklist.risk && checklist.kit;

