type Step = 'welcome' | 'phone' | 'registration' | 'recognition' | 'consent' | 'signature' | 'health' | 'healthInput' | 'arrival';

const TabletCheckinFlow: React.FC<{ setView: (view: View) => void }> = ({ setView }) => {
    const [step, setStep] = useState<Step>('welcome');
    const [clientName, setClientName] = useState('Anna');

    useEffect(() => {
        if (step === 'arrival') {
            const timer = setTimeout(() => {
                setStep('welcome');
                setClientName('Anna'); // Reset to default for demo loop
            }, 6000);
            return () => clearTimeout(timer);
        }
    }, [step]);

    const handlePhoneNext = (phone: string) => {
        if (phone.endsWith('0000')) {
            // New user simulation if number ends in 0000
            setStep('registration');
        } else {
            // Existing user (Anna)
            setStep('recognition');
        }
    };

    const handleRegistrationNext = (name: string) => {
        setClientName(name);
        setStep('recognition');
    };

    const renderStep = () => {
        switch (step) {
            case 'welcome':
                return <WelcomeScreen onNext={() => setStep('phone')} />;
            case 'phone':
                return <PhoneInputScreen onNext={handlePhoneNext} />;
            case 'registration':
                return <RegistrationScreen onNext={handleRegistrationNext} />;
            case 'recognition':
                return <ConfirmationScreen title={`Willkommen, ${clientName}.`} subtitle="Wir haben Ihren Termin für 09:00 Uhr vorbereitet." onNext={() => setStep('health')} buttonText="Check-in fortsetzen" />;
            // Re-ordered flow: Health Check -> Health Input (if needed) -> Consent -> Signature
            case 'health':
                return <HealthQuestionScreen onNext={() => setStep('consent')} onYes={() => setStep('healthInput')} />;
            case 'healthInput':
                return <HealthInputScreen onNext={() => setStep('consent')} />;
            case 'consent':
                return <ConsentScreen onNext={() => setStep('signature')} />;
            case 'signature':
                return <SignatureScreen onNext={() => setStep('arrival')} />;
            case 'arrival':
                return <ArrivalScreen />;
            default:
                return null;
        }
    };

    return (
        <div className="fixed inset-0 bg-p-background flex flex-col items-center justify-center p-8">
            <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-p-primary via-p-accent to-p-primary opacity-20"></div>
            <button onClick={() => setView('roleSelector')} className="absolute top-6 left-6 text-xs uppercase tracking-widest text-p-text/30 hover:text-p-primary transition">Exit Demo</button>

            <div className="w-full max-w-4xl flex items-center justify-center min-h-[600px] bg-white rounded-3xl shadow-soft border border-p-stone/50 p-8 md:p-16">
